import unittest
from candidate import separate_paren_groups

class TestSeparateParenGroups(unittest.TestCase):
    def test_normal_case_single_group(self):
        self.assertEqual(separate_paren_groups('()'), ['()'])

    def test_normal_case_multiple_groups(self):
        self.assertEqual(separate_paren_groups('( ) (( ))'), ['()', '(())'])

    def test_normal_case_complex_groups(self):
        self.assertEqual(separate_paren_groups('( ( ) ( ) )'), ['(()())'])

    def test_normal_case_nested_with_spaces(self):
        self.assertEqual(separate_paren_groups('( ) ( ) ( )'), ['()', '()', '()'])

    def test_empty_string(self):
        self.assertEqual(separate_paren_groups(''), [])

    def test_none_input(self):
        with self.assertRaises(TypeError):
            separate_paren_groups(None)

    def test_non_string_input(self):
        with self.assertRaises(TypeError):
            separate_paren_groups(123)

    def test_unbalanced_parentheses(self):
        with self.assertRaises(ValueError):
            separate_paren_groups('(()')

    def test_single_open_parenthesis(self):
        with self.assertRaises(ValueError):
            separate_paren_groups('(')

    def test_single_close_parenthesis(self):
        with self.assertRaises(ValueError):
            separate_paren_groups(')')

    def test_mixed_case_with_spaces(self):
        self.assertEqual(separate_paren_groups('( )   ( )   ( )'), ['()', '()', '()'])

    def test_long_complex_group(self):
        self.assertEqual(separate_paren_groups('((((()))))'), ['((((())))]')

    def test_multiple_empty_groups(self):
        self.assertEqual(separate_paren_groups('()()()'), ['()', '()', '()'])

    def test_odd_length_string(self):
        with self.assertRaises(ValueError):
            separate_paren_groups('(()()')

    def test_paren_string_with_non_parentheses(self):
        self.assertEqual(separate_paren_groups('abc(def)ghi'), ['(def)'])

    def test_paren_string_with_mixed_non_parentheses(self):
        self.assertEqual(separate_paren_groups('a(b)c(d)e(f)g'), ['(b)', '(d)', '(f)'])

    def test_all_closing_parentheses(self):
        with self.assertRaises(ValueError):
            separate_paren_groups(')(')

    def test_paren_string_with_whitespace(self):
        self.assertEqual(separate_paren_groups('( a ) ( b )'), ['(a)', '(b)'])

    def test_paren_string_with_only_spaces(self):
        self.assertEqual(separate_paren_groups('   '), [])

    def test_paren_string_with_multiple_spaces(self):
        self.assertEqual(separate_paren_groups('( )   ( )   ( )'), ['()', '()', '()'])
